<template><div class="app-container"><el-card style="max-width:600px;margin:30px auto"><h2>修改登录密码</h2><el-form label-position="top"><el-form-item label="原密码"><el-input v-model="form.oldPassword" type="password" show-password/></el-form-item><el-form-item label="新密码"><el-input v-model="form.newPassword" type="password" show-password maxlength="20" placeholder="请输入6至20位新密码"/></el-form-item><el-form-item label="再次输入新密码"><el-input v-model="repeat" type="password" show-password/></el-form-item><el-button type="primary" :loading="saving" @click="save">保存新密码</el-button></el-form></el-card></div></template>
<script setup>
import {ref} from 'vue';import request from '@/utils/request';import {ElMessage} from 'element-plus';const form=ref({oldPassword:'',newPassword:''}),repeat=ref(''),saving=ref(false);async function save(){if(!form.value.oldPassword||form.value.newPassword.length<6||form.value.newPassword.length>20)return ElMessage.warning('请填写原密码和6至20位新密码');if(form.value.newPassword!==repeat.value)return ElMessage.warning('两次输入的新密码不一致');saving.value=true;try{await request({url:'/system/user/profile/updatePwd',method:'put',data:form.value});ElMessage.success('登录密码已修改');form.value={oldPassword:'',newPassword:''};repeat.value=''}finally{saving.value=false}}
</script>
